output_text:
[
  {
    "id": "functional_interactions_only",
    "text": "Interactions should occur only at functional places: the cart station, a wide unobstructed cart-staging area, or next to a shelf.",
    "abstraction": {
      "state_properties": {
        "cart_station": "at(1,7)",
        "wide_cart_staging_area": {
          "and": [
            {
              "ge": [
                "freeWidthH",
                12
              ]
            },
            {
              "ge": [
                "freeWidthV",
                5
              ]
            },
            {
              "not": "adjShelf"
            }
          ]
        },
        "shelf_service_cell": "adjShelf",
        "functional_interaction_place": {
          "or": [
            "cart_station",
            "wide_cart_staging_area",
            "shelf_service_cell"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "INTERACT",
          {
            "not": "functional_interaction_place"
          }
        ]
      }
    }
  },
  {
    "id": "single_file_aisles_cart_free",
    "text": "Shopping carts are prohibited in single-file shelf aisles where the customer is between shelves.",
    "abstraction": {
      "state_properties": {
        "single_file_shelf_aisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "single_file_shelf_aisle"
        ]
      }
    }
  },
  {
    "id": "do_not_enter_single_file_with_cart",
    "text": "A customer must not move into a single-file shelf aisle while still holding or pushing a cart.",
    "abstraction": {
      "state_properties": {
        "single_file_shelf_aisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {
        "enter_single_file_with_cart": {
          "pre": {
            "and": [
              "hasCart",
              "MOVE"
            ]
          },
          "post": "single_file_shelf_aisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "enter_single_file_with_cart"
    }
  },
  {
    "id": "retrieve_parked_cart",
    "text": "Whenever a customer parks or lets go of a cart, they are obliged to retrieve it before the trip ends.",
    "abstraction": {
      "state_properties": {},
      "events": {
        "park_cart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "retrieve_cart": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "park_cart",
      "discharge": "retrieve_cart"
    }
  },
  {
    "id": "cartless_movement_only_in_pedestrian_aisles",
    "text": "After leaving the cart behind, a customer may move only at a cart-parking mouth or inside the narrow pedestrian shelf aisle.",
    "abstraction": {
      "state_properties": {
        "single_file_shelf_aisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        },
        "cart_parking_mouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "permitted_cartless_movement_zone": {
          "or": [
            "single_file_shelf_aisle",
            "cart_parking_mouth"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          {
            "not": "hasCart"
          },
          "MOVE",
          {
            "not": "permitted_cartless_movement_zone"
          }
        ]
      }
    }
  },
  {
    "id": "park_only_in_wide_unobstructed_areas",
    "text": "Carts may be parked only in wide unobstructed areas rather than beside shelves or in constricted aisles.",
    "abstraction": {
      "state_properties": {
        "wide_unobstructed_area": {
          "and": [
            {
              "ge": [
                "freeWidthH",
                12
              ]
            },
            {
              "ge": [
                "freeWidthV",
                5
              ]
            },
            {
              "not": "adjShelf"
            }
          ]
        }
      },
      "events": {
        "park_cart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "park_cart",
          {
            "not": "wide_unobstructed_area"
          }
        ]
      }
    }
  },
  {
    "id": "use_cart_at_cart_accessible_shelves",
    "text": "Shelf interactions from ordinary cart-accessible aisles require having the cart; cart-free shelf service is allowed only in single-file pedestrian aisles.",
    "abstraction": {
      "state_properties": {
        "single_file_shelf_aisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        },
        "cart_accessible_shelf_cell": {
          "and": [
            "adjShelf",
            {
              "not": "single_file_shelf_aisle"
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "INTERACT",
          "cart_accessible_shelf_cell",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  },
  {
    "id": "one_way_no_westbound",
    "text": "Customers should follow one-way circulation and never travel westbound.",
    "abstraction": {
      "state_properties": {},
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": "W"
    }
  }
]
